"""Domain-specific exceptions."""

from __future__ import annotations

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from pathlib import Path


class FlashcardsGeneratorError(Exception):
    """Base exception for all domain errors."""


class AnkiConnectError(FlashcardsGeneratorError):
    """Raised when AnkiConnect cannot complete an export operation."""

    def __init__(self, operation: str, reason: str) -> None:
        self.operation = operation
        self.reason = reason
        super().__init__(f"AnkiConnect {operation} failed: {reason}")


class SourceProcessingError(FlashcardsGeneratorError):
    """Raised when PDF source cannot be processed."""

    def __init__(self, source_path: Path, reason: str) -> None:
        self.source_path = source_path
        self.reason = reason
        super().__init__(f"Failed to process {source_path}: {reason}")


class GenerationError(FlashcardsGeneratorError):
    """Raised when flashcard generation fails."""

    def __init__(self, notebook_id: str, reason: str) -> None:
        self.notebook_id = notebook_id
        self.reason = reason
        super().__init__(f"Generation failed for {notebook_id}: {reason}")


class ArtifactDownloadError(FlashcardsGeneratorError):
    """Raised when artifact cannot be downloaded."""

    def __init__(self, artifact_id: str, reason: str) -> None:
        self.artifact_id = artifact_id
        self.reason = reason
        super().__init__(f"Download failed for {artifact_id}: {reason}")


class NotebookLMResponseError(RuntimeError, FlashcardsGeneratorError):
    """Raised when NotebookLM returns a syntactically valid invalid response."""

    def __init__(self, operation: str, reason: str) -> None:
        self.operation = operation
        self.reason = reason
        super().__init__(
            f"Invalid NotebookLM response for {operation}: {reason}"
        )


class NotebookCleanupError(FlashcardsGeneratorError):
    """Raised when notebook cleanup fails (non-critical)."""

    def __init__(self, notebook_id: str, reason: str) -> None:
        self.notebook_id = notebook_id
        self.reason = reason
        super().__init__(f"Cleanup failed for {notebook_id}: {reason}")


class CSVMergeError(FlashcardsGeneratorError):
    """Raised when CSV merge operation fails."""

    def __init__(self, folder_path: Path, reason: str) -> None:
        self.folder_path = folder_path
        self.reason = reason
        super().__init__(f"CSV merge failed for {folder_path}: {reason}")

"""DTO for CSV merge use case."""

from pathlib import Path, PurePath

from pydantic import BaseModel, Field, field_validator


class MergeCsvRequest(BaseModel):
    """Request to merge CSV flashcard files."""

    model_config = {"arbitrary_types_allowed": True}

    folder_path: Path
    output_filename: str = Field(default="merged_flashcards.csv")
    deduplicate: bool = Field(default=False)

    @field_validator("output_filename")
    @classmethod
    def validate_output_filename(cls, value: str) -> str:
        path = PurePath(value)
        if not value or path.is_absolute() or path.name != value:
            raise ValueError(
                "output_filename must be a nonempty relative basename"
            )
        return value

    recursive: bool = Field(default=True)

"""Data Transfer Objects for use cases."""

from flashcards_generator.application.dto.generate_request import (
    GenerateFlashcardsRequest,
)
from flashcards_generator.application.dto.merge_request import MergeCsvRequest

__all__ = ["GenerateFlashcardsRequest", "MergeCsvRequest"]

from pathlib import Path

import pytest

from flashcards_generator.domain.exceptions import (
    ArtifactDownloadError,
    FlashcardsGeneratorError,
    GenerationError,
    NotebookCleanupError,
    SourceProcessingError,
)


class TestExceptions:
    def test_flashcards_generator_error(self):
        with pytest.raises(FlashcardsGeneratorError):
            raise FlashcardsGeneratorError("Test error")

    def test_source_processing_error(self):
        path = Path("/path/to/file.pdf")
        error = SourceProcessingError(path, "PDF corrupted")

        assert error.source_path == path
        assert error.reason == "PDF corrupted"
        assert "Failed to process" in str(error)
        assert "PDF corrupted" in str(error)

    def test_generation_error(self):
        error = GenerationError("nb123", "API timeout")

        assert error.notebook_id == "nb123"
        assert error.reason == "API timeout"
        assert "Generation failed" in str(error)
        assert "nb123" in str(error)

    def test_artifact_download_error(self):
        error = ArtifactDownloadError("art456", "Network error")

        assert error.artifact_id == "art456"
        assert error.reason == "Network error"
        assert "Download failed" in str(error)
        assert "art456" in str(error)

    def test_notebook_cleanup_error(self):
        error = NotebookCleanupError("nb789", "Permission denied")

        assert error.notebook_id == "nb789"
        assert error.reason == "Permission denied"
        assert "Cleanup failed" in str(error)
        assert "nb789" in str(error)


class TestAbstractPorts:
    def test_deck_repository_port_save_not_implemented(self):
        from flashcards_generator.domain.ports.deck_repository import (
            DeckRepositoryPort,
        )

        class ConcreteRepo(DeckRepositoryPort):
            pass

        with pytest.raises(TypeError):
            ConcreteRepo()

    def test_flashcard_generator_port_not_implemented(self):
        from flashcards_generator.domain.ports.flashcard_generator import (
            FlashcardGeneratorPort,
        )

        class ConcreteGenerator(FlashcardGeneratorPort):
            pass

        with pytest.raises(TypeError):
            ConcreteGenerator()

